import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { requireSupabaseUser } from "../_shared/supabase-auth.ts";
import { errorResponse, jsonResponse, methodNotAllowed } from "../_shared/http.ts";
import { buildAbsoluteReturnUrl, isPicomVerifiedPlanKey, isAllowedCheckoutHost } from "../_shared/billing-allowlist.ts";
import { priceIdForPlan, readStripeConfig, stripeRequest } from "../_shared/billing-stripe.ts";

Deno.serve(async (request: Request) => {
  if (request.method === "OPTIONS") return jsonResponse({ ok: true });
  if (request.method !== "POST") return methodNotAllowed(["POST"]);

  const auth = await requireSupabaseUser(request);
  if (!auth.ok) return auth.response;

  const stripe = readStripeConfig();
  if (!stripe) return errorResponse("NOT_CONFIGURED", "PICOM Verified billing provider is not configured.", 503);

  const body = await request.json().catch(() => null) as Record<string, unknown> | null;
  const planKey = typeof body?.planKey === "string" ? body.planKey : "";
  const successReturnPath = typeof body?.successReturnPath === "string" ? body.successReturnPath : "";
  const cancelReturnPath = typeof body?.cancelReturnPath === "string" ? body.cancelReturnPath : "";
  const idempotencyKey = typeof body?.idempotencyKey === "string" ? body.idempotencyKey.trim() : "";

  if (!isPicomVerifiedPlanKey(planKey)) return errorResponse("VALIDATION_ERROR", "Choose a valid PICOM Verified plan.", 400);
  if ("providerPriceId" in (body ?? {}) || "priceId" in (body ?? {})) {
    return errorResponse("VALIDATION_ERROR", "Client-supplied price identifiers are not accepted.", 400);
  }
  const successUrl = buildAbsoluteReturnUrl(successReturnPath);
  const cancelUrl = buildAbsoluteReturnUrl(cancelReturnPath);
  if (!successUrl || !cancelUrl) return errorResponse("VALIDATION_ERROR", "Return URLs must use an allowlisted Account Center path.", 400);
  if (idempotencyKey.length < 8 || idempotencyKey.length > 200) {
    return errorResponse("VALIDATION_ERROR", "A valid idempotency key is required.", 400);
  }

  const serviceUrl = Deno.env.get("SUPABASE_URL");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!serviceUrl || !serviceKey) return errorResponse("NOT_CONFIGURED", "Supabase service role is not configured.", 503);
  const admin = createClient(serviceUrl, serviceKey, { auth: { persistSession: false } });

  const existingCheckout = await admin
    .from("billing_checkout_sessions")
    .select("id,provider_checkout_session_id,status")
    .eq("user_id", auth.user.id)
    .eq("idempotency_key", idempotencyKey)
    .maybeSingle();

  if (existingCheckout.data?.provider_checkout_session_id && existingCheckout.data.status !== "expired") {
    const existing = await stripeRequest(stripe, "GET", `checkout/sessions/${existingCheckout.data.provider_checkout_session_id}`);
    if (existing.ok && typeof existing.data.url === "string" && isAllowedCheckoutHost(existing.data.url)) {
      return jsonResponse({ data: { checkoutUrl: existing.data.url, provider: "stripe", planKey } });
    }
  }

  let customerId: string | null = null;
  const existingCustomer = await admin
    .from("billing_customers")
    .select("id,provider_customer_id")
    .eq("user_id", auth.user.id)
    .eq("provider", "stripe")
    .eq("status", "active")
    .maybeSingle();

  if (existingCustomer.data?.provider_customer_id) {
    customerId = existingCustomer.data.provider_customer_id;
  } else {
    const params = new URLSearchParams();
    params.set("metadata[picom_user_id]", auth.user.id);
    if (auth.user.email) params.set("email", auth.user.email);
    const created = await stripeRequest(stripe, "POST", "customers", params, `customer:${auth.user.id}`);
    if (!created.ok || typeof created.data.id !== "string") {
      return errorResponse("UNAVAILABLE", "Unable to create billing customer.", 502);
    }
    customerId = created.data.id;
    await admin.from("billing_customers").insert({
      user_id: auth.user.id,
      provider: "stripe",
      provider_customer_id: customerId,
      status: "active",
    });
  }

  const priceId = priceIdForPlan(stripe, planKey);
  const params = new URLSearchParams();
  params.set("mode", "subscription");
  params.set("customer", customerId);
  params.set("success_url", successUrl);
  params.set("cancel_url", cancelUrl);
  params.set("line_items[0][price]", priceId);
  params.set("line_items[0][quantity]", "1");
  params.set("client_reference_id", auth.user.id);
  params.set("metadata[picom_user_id]", auth.user.id);
  params.set("metadata[plan_key]", planKey);
  params.set("subscription_data[metadata][picom_user_id]", auth.user.id);
  params.set("subscription_data[metadata][plan_key]", planKey);

  const checkout = await stripeRequest(stripe, "POST", "checkout/sessions", params, idempotencyKey);
  if (!checkout.ok || typeof checkout.data.id !== "string" || typeof checkout.data.url !== "string") {
    return errorResponse("UNAVAILABLE", "Unable to create checkout session.", 502);
  }
  if (!isAllowedCheckoutHost(checkout.data.url)) {
    return errorResponse("UNAVAILABLE", "Provider returned an unsafe checkout URL.", 502);
  }

  await admin.from("billing_checkout_sessions").upsert({
    user_id: auth.user.id,
    plan_key: planKey,
    provider: "stripe",
    provider_checkout_session_id: checkout.data.id,
    idempotency_key: idempotencyKey,
    status: "open",
    success_return_path: successReturnPath,
    cancel_return_path: cancelReturnPath,
  }, { onConflict: "user_id,idempotency_key" });

  return jsonResponse({
    data: {
      checkoutUrl: checkout.data.url,
      provider: "stripe",
      planKey,
    },
  });
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { requireSupabaseUser } from "../_shared/supabase-auth.ts";
import { errorResponse, jsonResponse, methodNotAllowed } from "../_shared/http.ts";
import { buildAbsoluteReturnUrl, isAllowedPortalHost } from "../_shared/billing-allowlist.ts";
import { readStripeConfig, stripeRequest } from "../_shared/billing-stripe.ts";

Deno.serve(async (request: Request) => {
  if (request.method === "OPTIONS") return jsonResponse({ ok: true });
  if (request.method !== "POST") return methodNotAllowed(["POST"]);

  const auth = await requireSupabaseUser(request);
  if (!auth.ok) return auth.response;

  const stripe = readStripeConfig();
  if (!stripe) return errorResponse("NOT_CONFIGURED", "PICOM Verified billing provider is not configured.", 503);

  const body = await request.json().catch(() => null) as Record<string, unknown> | null;
  const returnPath = typeof body?.returnPath === "string" ? body.returnPath : "/account/billing";
  const returnUrl = buildAbsoluteReturnUrl(returnPath);
  if (!returnUrl) return errorResponse("VALIDATION_ERROR", "Return URL must use an allowlisted Account Center path.", 400);

  const serviceUrl = Deno.env.get("SUPABASE_URL");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!serviceUrl || !serviceKey) return errorResponse("NOT_CONFIGURED", "Supabase service role is not configured.", 503);
  const admin = createClient(serviceUrl, serviceKey, { auth: { persistSession: false } });

  const customer = await admin
    .from("billing_customers")
    .select("provider_customer_id")
    .eq("user_id", auth.user.id)
    .eq("provider", "stripe")
    .eq("status", "active")
    .maybeSingle();

  if (!customer.data?.provider_customer_id) {
    return errorResponse("NOT_FOUND", "No billing customer exists for this account yet.", 404);
  }

  const params = new URLSearchParams();
  params.set("customer", customer.data.provider_customer_id);
  params.set("return_url", returnUrl);
  const portal = await stripeRequest(stripe, "POST", "billing_portal/sessions", params);
  if (!portal.ok || typeof portal.data.url !== "string" || !isAllowedPortalHost(portal.data.url)) {
    return errorResponse("UNAVAILABLE", "Unable to create a secure billing portal session.", 502);
  }

  return jsonResponse({ data: { portalUrl: portal.data.url, provider: "stripe" } });
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { errorResponse, jsonResponse, methodNotAllowed } from "../_shared/http.ts";
import { readStripeConfig, sha256Hex, verifyStripeWebhookSignature } from "../_shared/billing-stripe.ts";

type StripeEvent = {
  id?: string;
  type?: string;
  api_version?: string;
  created?: number;
  data?: { object?: Record<string, unknown> };
};

const HANDLED = new Set([
  "checkout.session.completed",
  "customer.subscription.created",
  "customer.subscription.updated",
  "customer.subscription.deleted",
  "invoice.paid",
  "invoice.payment_failed",
  "invoice.payment_action_required",
  "charge.refunded",
  "charge.dispute.created",
  "charge.dispute.closed",
  "identity.verification_session.verified",
  "identity.verification_session.requires_input",
  "identity.verification_session.canceled",
]);

function mapSubscriptionStatus(status: string | undefined, cancelAtPeriodEnd: boolean): string {
  switch (status) {
    case "incomplete":
    case "incomplete_expired":
      return status === "incomplete_expired" ? "expired" : "incomplete";
    case "trialing":
      return "trialing";
    case "active":
      return cancelAtPeriodEnd ? "active" : "active";
    case "past_due":
      return "past_due";
    case "canceled":
      return "cancelled";
    case "unpaid":
      return "unpaid";
    case "paused":
      return "paused";
    default:
      return "incomplete";
  }
}

function asString(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value : null;
}

function asNumber(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

Deno.serve(async (request: Request) => {
  if (request.method !== "POST") return methodNotAllowed(["POST"]);

  const stripe = readStripeConfig();
  if (!stripe) return errorResponse("NOT_CONFIGURED", "Billing webhook processing is not configured.", 503);

  const serviceUrl = Deno.env.get("SUPABASE_URL");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!serviceUrl || !serviceKey) return errorResponse("NOT_CONFIGURED", "Supabase service role is not configured.", 503);

  const rawBody = await request.text();
  if (!rawBody) return errorResponse("VALIDATION_ERROR", "Webhook body is required.", 400);

  const signature = request.headers.get("Stripe-Signature");
  const isIdentity = rawBody.includes("identity.verification_session");
  const secret = isIdentity && stripe.identityWebhookSecret ? stripe.identityWebhookSecret : stripe.webhookSecret;
  const verified = await verifyStripeWebhookSignature(rawBody, signature, secret);
  if (!verified.ok) return errorResponse("WEBHOOK_INVALID", "Webhook signature validation failed.", 401);

  let event: StripeEvent;
  try {
    event = JSON.parse(rawBody) as StripeEvent;
  } catch {
    return errorResponse("VALIDATION_ERROR", "Webhook payload must be JSON.", 400);
  }

  const eventId = asString(event.id);
  const eventType = asString(event.type);
  if (!eventId || !eventType) return errorResponse("VALIDATION_ERROR", "Webhook event identity is required.", 400);

  const admin = createClient(serviceUrl, serviceKey, { auth: { persistSession: false } });
  const payloadHash = await sha256Hex(rawBody);

  const insert = await admin.from("provider_webhook_events").insert({
    provider: "stripe",
    provider_event_id: eventId,
    event_type: eventType,
    api_version: asString(event.api_version),
    payload_hash: payloadHash,
    payload_created_at: event.created ? new Date(event.created * 1000).toISOString() : null,
    processing_status: "processing",
    processing_started_at: new Date().toISOString(),
  }).select("id").maybeSingle();

  if (insert.error) {
    if (insert.error.code === "23505") {
      return jsonResponse({ ok: true, duplicate: true });
    }
    return errorResponse("UNAVAILABLE", "Unable to claim webhook event.", 500);
  }

  if (!HANDLED.has(eventType)) {
    await admin.from("provider_webhook_events").update({
      processing_status: "ignored",
      processed_at: new Date().toISOString(),
    }).eq("provider", "stripe").eq("provider_event_id", eventId);
    return jsonResponse({ ok: true, ignored: true });
  }

  try {
    const object = event.data?.object ?? {};
    const metadata = (object.metadata as Record<string, unknown> | undefined) ?? {};
    let userId = asString(metadata.picom_user_id);

    if (eventType.startsWith("customer.subscription.") || eventType === "checkout.session.completed") {
      const subscriptionId = eventType === "checkout.session.completed"
        ? asString(object.subscription)
        : asString(object.id);
      if (!userId && asString(object.client_reference_id)) userId = asString(object.client_reference_id);
      if (!userId && asString(object.customer)) {
        const customer = await admin.from("billing_customers").select("user_id").eq("provider_customer_id", asString(object.customer)).maybeSingle();
        userId = customer.data?.user_id ?? null;
      }

      if (userId && subscriptionId) {
        const customerRow = await admin.from("billing_customers").select("id").eq("user_id", userId).eq("provider", "stripe").maybeSingle();
        const status = mapSubscriptionStatus(asString(object.status) ?? undefined, object.cancel_at_period_end === true);
        const planKey = asString(metadata.plan_key) === "picom_verified_yearly" ? "picom_verified_yearly" : "picom_verified_monthly";
        const priceId = asString(((object.items as { data?: Array<{ price?: { id?: string } }> } | undefined)?.data?.[0]?.price?.id)
          ?? asString(object.price)
          ?? "unknown";
        const stateVersion = asNumber(object.created) ?? Math.floor(Date.now() / 1000);
        const existing = await admin.from("picom_verified_subscriptions").select("id,provider_state_version").eq("provider_subscription_id", subscriptionId).maybeSingle();
        if (!existing.data || (existing.data.provider_state_version ?? 0) <= stateVersion) {
          const payload = {
            user_id: userId,
            billing_customer_id: customerRow.data?.id,
            product_key: "picom_verified",
            plan_key: planKey,
            provider: "stripe",
            provider_subscription_id: subscriptionId,
            provider_price_id: priceId,
            status: status === "past_due" ? "grace_period" : status,
            cancel_at_period_end: object.cancel_at_period_end === true,
            current_period_start: asNumber(object.current_period_start) ? new Date((object.current_period_start as number) * 1000).toISOString() : null,
            current_period_end: asNumber(object.current_period_end) ? new Date((object.current_period_end as number) * 1000).toISOString() : null,
            grace_until: status === "past_due" && asNumber(object.current_period_end)
              ? new Date(((object.current_period_end as number) + 3 * 24 * 3600) * 1000).toISOString()
              : null,
            cancelled_at: status === "cancelled" ? new Date().toISOString() : null,
            ended_at: status === "expired" || status === "cancelled" ? new Date().toISOString() : null,
            last_payment_status: eventType,
            provider_state_version: stateVersion,
          };
          if (existing.data?.id) {
            await admin.from("picom_verified_subscriptions").update(payload).eq("id", existing.data.id);
          } else if (payload.billing_customer_id) {
            await admin.from("picom_verified_subscriptions").insert(payload);
          }
          await admin.rpc("reconcile_picom_verified_entitlements", {
            target_user_id: userId,
            source_event: eventType,
          });
          if (status === "active" || status === "trialing" || status === "grace_period") {
            await admin.rpc("enqueue_email_for_user_event", {
              target_user_id: userId,
              target_template_id: "subscription_confirmation",
              target_category: "billing",
              target_parameters: { summary: "Your PICOM Verified subscription was updated.", reference: eventType },
              target_idempotency_key: `verified-sub:${eventId}`,
              target_correlation_id: eventId,
              target_priority: 80,
              target_hook_name: "picom_verified_subscription",
              target_source_record_id: eventId,
            });
          } else if (eventType === "invoice.payment_failed" || status === "past_due" || status === "unpaid") {
            await admin.rpc("enqueue_email_for_user_event", {
              target_user_id: userId,
              target_template_id: "payment_failure",
              target_category: "billing",
              target_parameters: { summary: "A PICOM Verified payment requires attention.", reference: eventType },
              target_idempotency_key: `verified-payfail:${eventId}`,
              target_correlation_id: eventId,
              target_priority: 90,
              target_hook_name: "picom_verified_payment",
              target_source_record_id: eventId,
            });
          }
        }
      }
    }

    if (eventType.startsWith("invoice.")) {
      const subscriptionId = asString(object.subscription);
      const invoiceId = asString(object.id);
      if (subscriptionId && invoiceId) {
        const sub = await admin.from("picom_verified_subscriptions").select("id,user_id").eq("provider_subscription_id", subscriptionId).maybeSingle();
        if (sub.data) {
          await admin.from("billing_invoices").upsert({
            subscription_id: sub.data.id,
            user_id: sub.data.user_id,
            provider_invoice_id: invoiceId,
            provider_payment_intent_id: asString(object.payment_intent),
            status: asString(object.status) === "paid" ? "paid" : asString(object.status) === "open" ? "open" : "failed",
            amount_due_minor: asNumber(object.amount_due) ?? 0,
            amount_paid_minor: asNumber(object.amount_paid) ?? 0,
            currency: (asString(object.currency) ?? "usd").toUpperCase(),
            hosted_invoice_url: asString(object.hosted_invoice_url),
            invoice_pdf_url: asString(object.invoice_pdf),
            paid_at: asString(object.status) === "paid" ? new Date().toISOString() : null,
            failed_at: eventType === "invoice.payment_failed" ? new Date().toISOString() : null,
          }, { onConflict: "provider_invoice_id" });
        }
      }
    }

    if (eventType.startsWith("identity.verification_session.")) {
      const sessionId = asString(object.id);
      const metaUser = asString(metadata.picom_user_id);
      if (sessionId) {
        const status = eventType.endsWith(".verified")
          ? "verified"
          : eventType.endsWith(".requires_input")
          ? "requires_input"
          : "canceled";
        const session = await admin.from("account_verification_sessions").select("id,user_id,verification_case_id").eq("provider_session_id", sessionId).maybeSingle();
        const targetUser = session.data?.user_id ?? metaUser;
        if (session.data) {
          await admin.from("account_verification_sessions").update({
            status,
            completed_at: status === "verified" || status === "canceled" ? new Date().toISOString() : null,
            provider_state_version: asNumber(object.created) ?? Math.floor(Date.now() / 1000),
          }).eq("id", session.data.id);
          await admin.from("verification_cases").update({
            status: status === "verified" ? "verified" : status === "requires_input" ? "requires_input" : "cancelled",
            reviewed_at: status === "verified" ? new Date().toISOString() : null,
          }).eq("id", session.data.verification_case_id);
        }
        if (targetUser) {
          await admin.rpc("reconcile_verified_account_badge", {
            target_user_id: targetUser,
            source_event: eventType,
          });
        }
      }
    }

    await admin.from("provider_webhook_events").update({
      processing_status: "processed",
      processed_at: new Date().toISOString(),
    }).eq("provider", "stripe").eq("provider_event_id", eventId);

    return jsonResponse({ ok: true });
  } catch {
    await admin.from("provider_webhook_events").update({
      processing_status: "retry_scheduled",
      next_retry_at: new Date(Date.now() + 60_000).toISOString(),
      last_error_code: "PROCESSING_FAILED",
      last_error_message_safe: "Webhook processing failed.",
    }).eq("provider", "stripe").eq("provider_event_id", eventId);
    return errorResponse("UNAVAILABLE", "Webhook processing failed and will be retried.", 500);
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { requireSupabaseUser } from "../_shared/supabase-auth.ts";
import { errorResponse, jsonResponse, methodNotAllowed } from "../_shared/http.ts";
import { buildAbsoluteReturnUrl } from "../_shared/billing-allowlist.ts";
import { readStripeConfig, stripeRequest } from "../_shared/billing-stripe.ts";

Deno.serve(async (request: Request) => {
  if (request.method === "OPTIONS") return jsonResponse({ ok: true });
  if (request.method !== "POST") return methodNotAllowed(["POST"]);

  const auth = await requireSupabaseUser(request);
  if (!auth.ok) return auth.response;

  const body = await request.json().catch(() => null) as Record<string, unknown> | null;
  const returnPath = typeof body?.returnPath === "string" ? body.returnPath : "/account/verification";
  const returnUrl = buildAbsoluteReturnUrl(returnPath);
  if (!returnUrl) return errorResponse("VALIDATION_ERROR", "Return URL must use an allowlisted Account Center path.", 400);

  const serviceUrl = Deno.env.get("SUPABASE_URL");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!serviceUrl || !serviceKey) return errorResponse("NOT_CONFIGURED", "Supabase service role is not configured.", 503);
  const admin = createClient(serviceUrl, serviceKey, { auth: { persistSession: false } });

  const userSummary = await auth.supabase.rpc("get_picom_verified_summary");
  if (userSummary.error) {
    return errorResponse("UNAVAILABLE", "Unable to load PICOM Verified summary.", 500);
  }
  const entitlements = (userSummary.data as { entitlements?: { verifiedBadgeEligible?: boolean } } | null)?.entitlements;
  if (!entitlements?.verifiedBadgeEligible) {
    return errorResponse("FORBIDDEN", "An active PICOM Verified subscription is required before account verification.", 403);
  }

  const openSession = await admin
    .from("account_verification_sessions")
    .select("id,status,provider_session_id")
    .eq("user_id", auth.user.id)
    .in("status", ["pending", "requires_input", "processing"])
    .maybeSingle();
  if (openSession.data) {
    return jsonResponse({
      data: {
        sessionUrl: null,
        status: openSession.data.status,
        provider: "stripe_identity",
        message: "An open verification session already exists.",
      },
    });
  }

  const stripe = readStripeConfig();
  if (!stripe) {
    const caseInsert = await admin.from("verification_cases").insert({
      subject_type: "user",
      subject_id: auth.user.id,
      verification_type: "picom_verified_account",
      status: "pending",
      provider: "manual_review",
      submitted_at: new Date().toISOString(),
      metadata: { reason: "provider_not_configured" },
    }).select("id").single();
    if (caseInsert.error || !caseInsert.data) {
      return errorResponse("NOT_CONFIGURED", "Verification provider is not configured.", 503);
    }
    await admin.from("account_verification_sessions").insert({
      user_id: auth.user.id,
      verification_case_id: caseInsert.data.id,
      provider: "manual_review",
      status: "pending",
      return_url: returnUrl,
    });
    return errorResponse("NOT_CONFIGURED", "Identity verification provider credentials are not configured.", 503);
  }

  const caseInsert = await admin.from("verification_cases").insert({
    subject_type: "user",
    subject_id: auth.user.id,
    verification_type: "picom_verified_account",
    status: "pending",
    provider: "stripe_identity",
    submitted_at: new Date().toISOString(),
    metadata: {},
  }).select("id").single();
  if (caseInsert.error || !caseInsert.data) {
    return errorResponse("UNAVAILABLE", "Unable to create verification case.", 500);
  }

  const params = new URLSearchParams();
  params.set("type", "document");
  params.set("metadata[picom_user_id]", auth.user.id);
  params.set("return_url", returnUrl);
  const session = await stripeRequest(stripe, "POST", "identity/verification_sessions", params);
  if (!session.ok || typeof session.data.id !== "string") {
    return errorResponse("UNAVAILABLE", "Unable to create identity verification session.", 502);
  }

  await admin.from("account_verification_sessions").insert({
    user_id: auth.user.id,
    verification_case_id: caseInsert.data.id,
    provider: "stripe_identity",
    provider_session_id: session.data.id,
    status: "pending",
    return_url: returnUrl,
  });

  const url = typeof session.data.url === "string" ? session.data.url : null;
  return jsonResponse({
    data: {
      sessionUrl: url,
      status: "pending",
      provider: "stripe_identity",
    },
  });
});

export type BillingProviderName = "stripe";

export type StripeConfig = Readonly<{
  secretKey: string;
  webhookSecret: string;
  identityWebhookSecret: string | null;
  monthlyPriceId: string;
  yearlyPriceId: string;
}>;

export function readStripeConfig(): StripeConfig | null {
  const provider = (Deno.env.get("BILLING_PROVIDER")?.trim() || "stripe").toLowerCase();
  if (provider !== "stripe") return null;
  const secretKey = Deno.env.get("STRIPE_SECRET_KEY")?.trim() ?? "";
  const webhookSecret = Deno.env.get("STRIPE_WEBHOOK_SECRET")?.trim() ?? "";
  const monthlyPriceId = Deno.env.get("STRIPE_PICOM_VERIFIED_MONTHLY_PRICE_ID")?.trim() ?? "";
  const yearlyPriceId = Deno.env.get("STRIPE_PICOM_VERIFIED_YEARLY_PRICE_ID")?.trim() ?? "";
  if (!secretKey || !webhookSecret || !monthlyPriceId || !yearlyPriceId) return null;
  return {
    secretKey,
    webhookSecret,
    identityWebhookSecret: Deno.env.get("STRIPE_IDENTITY_WEBHOOK_SECRET")?.trim() || null,
    monthlyPriceId,
    yearlyPriceId,
  };
}

export function priceIdForPlan(config: StripeConfig, planKey: "picom_verified_monthly" | "picom_verified_yearly"): string {
  return planKey === "picom_verified_yearly" ? config.yearlyPriceId : config.monthlyPriceId;
}

export async function stripeRequest(
  config: StripeConfig,
  method: string,
  path: string,
  body?: URLSearchParams,
  idempotencyKey?: string,
): Promise<{ ok: true; data: Record<string, unknown> } | { ok: false; status: number; code: string; message: string }> {
  const headers: Record<string, string> = {
    Authorization: `Bearer ${config.secretKey}`,
  };
  if (body) headers["Content-Type"] = "application/x-www-form-urlencoded";
  if (idempotencyKey) headers["Idempotency-Key"] = idempotencyKey;

  const response = await fetch(`https://api.stripe.com/v1/${path.replace(/^\//, "")}`, {
    method,
    headers,
    body: body?.toString(),
  });

  const json = await response.json().catch(() => ({})) as Record<string, unknown>;
  if (!response.ok) {
    const error = (json.error as { code?: string; message?: string } | undefined) ?? {};
    return {
      ok: false,
      status: response.status,
      code: error.code ?? "STRIPE_ERROR",
      message: "Stripe request failed.",
    };
  }
  return { ok: true, data: json };
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let mismatch = 0;
  for (let i = 0; i < a.length; i += 1) mismatch |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return mismatch === 0;
}

export async function verifyStripeWebhookSignature(
  rawBody: string,
  signatureHeader: string | null,
  secret: string,
  toleranceSeconds = 300,
): Promise<{ ok: true; timestamp: number } | { ok: false; reason: string }> {
  if (!signatureHeader) return { ok: false, reason: "missing_signature" };
  const parts = Object.fromEntries(
    signatureHeader.split(",").map((part) => {
      const [key, value] = part.split("=");
      return [key?.trim() ?? "", value?.trim() ?? ""];
    }),
  );
  const timestamp = Number(parts.t);
  const signature = parts.v1;
  if (!Number.isFinite(timestamp) || !signature) return { ok: false, reason: "invalid_signature_header" };
  const age = Math.abs(Math.floor(Date.now() / 1000) - timestamp);
  if (age > toleranceSeconds) return { ok: false, reason: "timestamp_out_of_tolerance" };

  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey("raw", encoder.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const mac = await crypto.subtle.sign("HMAC", key, encoder.encode(`${timestamp}.${rawBody}`));
  const digest = Array.from(new Uint8Array(mac)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
  if (!timingSafeEqual(digest, signature)) return { ok: false, reason: "signature_mismatch" };
  return { ok: true, timestamp };
}

export async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return Array.from(new Uint8Array(digest)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

const ACCOUNT_ORIGIN = Deno.env.get("PICOM_ACCOUNT_CENTER_URL")?.trim() || "https://account.picom.gg";
const APP_ORIGIN = Deno.env.get("PICOM_APP_URL")?.trim() || "https://app.picom.gg";

const ALLOWED_ORIGINS = new Set([
  ACCOUNT_ORIGIN.replace(/\/$/, ""),
  APP_ORIGIN.replace(/\/$/, ""),
  "https://account.picom.gg",
  "https://app.picom.gg",
  "https://picom.gg",
]);

const ALLOWED_RETURN_PATHS = new Set([
  "/verified",
  "/verified/status",
  "/verified/checkout",
  "/account/billing",
  "/account/verification",
  "/account/overview",
]);

export function isAllowedReturnPath(path: string): boolean {
  if (typeof path !== "string") return false;
  const trimmed = path.trim();
  if (!trimmed.startsWith("/") || trimmed.startsWith("//") || trimmed.includes("://")) return false;
  const normalized = trimmed.split("?")[0]?.split("#")[0] ?? "";
  return ALLOWED_RETURN_PATHS.has(normalized);
}

export function buildAbsoluteReturnUrl(path: string): string | null {
  if (!isAllowedReturnPath(path)) return null;
  return new URL(path, `${ACCOUNT_ORIGIN.replace(/\/$/, "")}/`).toString();
}

export function isAllowedCheckoutHost(url: string): boolean {
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "https:") return false;
    const host = parsed.hostname.toLowerCase();
    return host === "checkout.stripe.com" || host.endsWith(".stripe.com");
  } catch {
    return false;
  }
}

export function isAllowedPortalHost(url: string): boolean {
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "https:") return false;
    const host = parsed.hostname.toLowerCase();
    return host === "billing.stripe.com" || host.endsWith(".stripe.com");
  } catch {
    return false;
  }
}

export function isAllowedAccountOrigin(url: string): boolean {
  try {
    const parsed = new URL(url);
    return parsed.protocol === "https:" && ALLOWED_ORIGINS.has(`${parsed.protocol}//${parsed.host}`);
  } catch {
    return false;
  }
}

