import type { PlatformServiceError, PlatformServiceResult } from "../../types/verificationBusiness/shared";

type QueryFailure = Readonly<{ code?: string; message?: string }>;
type QueryResponse = Readonly<{ data: unknown; error: QueryFailure | null }>;

interface PlatformQuery extends PromiseLike<QueryResponse> {
  select(columns: string): PlatformQuery;
  eq(column: string, value: unknown): PlatformQuery;
  order(column: string, options?: Readonly<{ ascending?: boolean }>): PlatformQuery;
  limit(count: number): PlatformQuery;
}

interface PlatformClient {
  from(relation: string): PlatformQuery;
  rpc(functionName: string, parameters?: Record<string, unknown>): PromiseLike<QueryResponse>;
  auth: {
    getSession(): PromiseLike<{ data: { session: { access_token?: string; user?: { id?: string } } | null } }>;
  };
}

type Row = Record<string, unknown>;

function platformClient(): PlatformClient | null {
  return getSupabaseClient() as unknown as PlatformClient | null;
}

function unavailable<T>(): PlatformServiceResult<T> {
  return {
    ok: false,
    error: {
      code: "NOT_CONFIGURED",
      message: "PICOM Verified billing is unavailable until Supabase is configured.",
    },
  };
}

function mapFailure(error: QueryFailure | null): PlatformServiceError {
  if (error?.code === "42501") return { code: "FORBIDDEN", message: "You do not have permission to perform this action." };
  if (error?.code === "PGRST116") return { code: "NOT_FOUND", message: "The requested billing record was not found." };
  if (error?.message?.toLowerCase().includes("not configured")) {
    return { code: "NOT_CONFIGURED", message: "PICOM Verified billing provider is not configured." };
  }
  return { code: "UNAVAILABLE", message: "Picom could not complete this billing request right now." };
}

function functionsBaseUrl(): string | null {
  const url = import.meta.env.VITE_SUPABASE_URL;
  if (!url || typeof url !== "string" || !url.trim()) return null;
  return `${url.replace(/\/$/, "")}/functions/v1`;
}

async function authHeader(): Promise<string | null> {
  const client = platformClient();
  if (!client) return null;
  const { data } = await client.auth.getSession();
  const token = data.session?.access_token;
  return token ? `Bearer ${token}` : null;
}

async function invokeJson<T>(path: string, init?: RequestInit): Promise<PlatformServiceResult<T>> {
  const base = functionsBaseUrl();
  if (!base) return unavailable();
  const authorization = await authHeader();
  if (!authorization) return { ok: false, error: { code: "UNAUTHORIZED", message: "Sign in to manage PICOM Verified." } };

  let response: Response;
  try {
    response = await fetch(`${base}/${path}`, {
      ...init,
      headers: {
        "Content-Type": "application/json",
        Authorization: authorization,
        ...(init?.headers ?? {}),
      },
    });
  } catch {
    return { ok: false, error: { code: "UNAVAILABLE", message: "Picom could not reach billing services." } };
  }

  const payload = (await response.json().catch(() => null)) as
    | { data?: T; error?: { code?: string; message?: string } }
    | T
    | null;

  if (!response.ok) {
    const err = payload && typeof payload === "object" && "error" in payload ? payload.error : null;
    if (response.status === 503) return { ok: false, error: { code: "NOT_CONFIGURED", message: err?.message ?? "Billing provider is not configured." } };
    return { ok: false, error: mapFailure({ code: err?.code, message: err?.message }) };
  }

  if (payload && typeof payload === "object" && "data" in payload && payload.data !== undefined) {
    return { ok: true, data: payload.data };
  }
  return { ok: true, data: payload as T };
}

function asRows(data: unknown): readonly Row[] {
  return Array.isArray(data) ? data.filter((row): row is Row => typeof row === "object" && row !== null) : [];
}

export type VerificationSessionResult = Readonly<{
  sessionUrl: string | null;
  status: string;
  provider: string;
  message?: string;
}>;

export const picomVerifiedService = {
  async getSummary(): Promise<PlatformServiceResult<PicomVerifiedPublicSummary>> {
    const client = platformClient();
    if (!client) return unavailable();
    const response = await client.rpc("get_picom_verified_summary");
    if (response.error) return { ok: false, error: mapFailure(response.error) };
    return { ok: true, data: response.data as PicomVerifiedPublicSummary };
  },

  async listCatalog(): Promise<PlatformServiceResult<readonly BillingCatalogPlan[]>> {
    const client = platformClient();
    if (!client) return unavailable();
    const response = await client
      .from("billing_catalog_public")
      .select("plan_key,billing_interval,currency,amount_minor,status")
      .order("billing_interval", { ascending: true });
    if (response.error) return { ok: false, error: mapFailure(response.error) };
    return {
      ok: true,
      data: asRows(response.data).map((row) => ({
        planKey: String(row.plan_key) as BillingCatalogPlan["planKey"],
        billingInterval: String(row.billing_interval) as BillingCatalogPlan["billingInterval"],
        currency: String(row.currency ?? "USD"),
        amountMinor: typeof row.amount_minor === "number" ? row.amount_minor : 0,
        status: "active" as const,
      })),
    };
  },

  async createCheckout(input: CreateCheckoutInput): Promise<PlatformServiceResult<CreateCheckoutResult>> {
    return invokeJson<CreateCheckoutResult>("billing-checkout", {
      method: "POST",
      body: JSON.stringify(input),
    });
  },

  async createPortal(returnPath = "/account/billing"): Promise<PlatformServiceResult<CreatePortalResult>> {
    return invokeJson<CreatePortalResult>("billing-portal", {
      method: "POST",
      body: JSON.stringify({ returnPath }),
    });
  },

  async createVerificationSession(returnPath = "/account/verification"): Promise<PlatformServiceResult<VerificationSessionResult>> {
    return invokeJson<VerificationSessionResult>("verification-account-session", {
      method: "POST",
      body: JSON.stringify({ returnPath }),
    });
  },

  async resolveAdEligibility(placement: string, contentKind?: string): Promise<PlatformServiceResult<AdEligibilityDecision>> {
    const client = platformClient();
    if (!client) return unavailable();
    const { data: sessionData } = await client.auth.getSession();
    const userId = sessionData.session?.user?.id ?? null;
    const response = await client.rpc("resolve_ad_eligibility", {
      target_user_id: userId,
      target_placement: placement,
      target_context: { contentKind: contentKind ?? null },
    });
    if (response.error) return { ok: false, error: mapFailure(response.error) };
    return { ok: true, data: response.data as AdEligibilityDecision };
  },
};

import type { AdPlacement, AdEligibilityDecision, AdContentKind } from "../types/ads/adEligibility";

const PAID_PLACEMENTS = new Set<AdPlacement>([
  "feed",
  "feed_inline",
  "companion_rail",
  "community_rail",
  "live_now",
  "events",
  "profile",
  "search",
  "notification",
  "business_sponsored",
]);

const ORGANIC_KINDS = new Set<AdContentKind>([
  "organic_business",
  "organic_creator",
  "organic_publisher",
  "security_announcement",
  "service_announcement",
]);

export function resolveAdEligibilityLocal(input: {
  placement: string;
  contentKind?: string | null;
  serverDecision?: AdEligibilityDecision | null;
  cachedAdFreeActive?: boolean | null;
  cachedAdFreeExpiresAt?: string | null;
  now?: string;
}): AdEligibilityDecision {
  if (input.serverDecision) {
    return input.serverDecision;
  }

  const placement = input.placement.trim().toLowerCase() as AdPlacement;
  const contentKind = (input.contentKind ?? "").trim().toLowerCase() as AdContentKind;

  if (ORGANIC_KINDS.has(contentKind)) {
    return { eligible: false, reason: "not_paid_placement", placement, contentKind };
  }

  const now = Date.parse(input.now ?? new Date().toISOString());
  const cacheExpiry = input.cachedAdFreeExpiresAt ? Date.parse(input.cachedAdFreeExpiresAt) : null;
  const cacheValid =
    input.cachedAdFreeActive === true &&
    cacheExpiry !== null &&
    !Number.isNaN(now) &&
    !Number.isNaN(cacheExpiry) &&
    cacheExpiry > now;

  if (cacheValid) {
    return { eligible: false, reason: "ad_free_entitlement", placement };
  }

  if (!PAID_PLACEMENTS.has(placement)) {
    return { eligible: false, reason: "unknown_placement", placement };
  }

  return { eligible: true, reason: "eligible_for_paid_placement", placement };
}

import { useCallback, useEffect, useState } from "react";
import { accountCenterUrls } from "../../config/accountCenterUrls";
import { translateSettings } from "../../services/settings/settingsI18n";
import type { UiLanguage } from "../../services/settingsService";
import { picomVerifiedService } from "../../services/verificationBusiness/picomVerifiedService";
import {
  readVerifiedEntitlementCache,
  writeVerifiedEntitlementCache,
} from "../../services/verificationBusiness/verifiedEntitlementCache";
import type { PicomVerifiedPublicSummary } from "../../types/verificationBusiness/picomVerified";
import { isAllowedVerifiedExternalUrl } from "../../services/desktop/verifiedExternalUrlAllowlist";
import * as externalLinkService from "../../services/desktop/externalLinkService";
import { getSupabaseClient } from "../../services/supabase/supabaseClient";

export type PicomVerifiedDesktopCardProps = Readonly<{
  language: UiLanguage;
  onOpenAccountCenter: (url: string) => void;
}>;

export function PicomVerifiedDesktopCard({ language, onOpenAccountCenter }: PicomVerifiedDesktopCardProps) {
  const t = (key: Parameters<typeof translateSettings>[0]) => translateSettings(key, language);
  const [userId, setUserId] = useState<string | null>(null);
  const [summary, setSummary] = useState<PicomVerifiedPublicSummary | null>(null);
  const [fromCache, setFromCache] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    const client = getSupabaseClient();
    if (!client) return;
    void client.auth.getSession().then(({ data }) => {
      setUserId(data.session?.user?.id ?? null);
    });
  }, []);

  const refresh = useCallback(async () => {
    if (!userId) return;
    setRefreshing(true);
    setError(null);
    const result = await picomVerifiedService.getSummary();
    if (result.ok) {
      setSummary(result.data);
      writeVerifiedEntitlementCache(userId, result.data);
      setFromCache(false);
    } else {
      const cached = readVerifiedEntitlementCache(userId);
      if (cached) {
        setSummary({
          subscriptionStatus: cached.subscriptionStatus as PicomVerifiedPublicSummary["subscriptionStatus"],
          planKey: null,
          currentPeriodEnd: null,
          cancelAtPeriodEnd: false,
          entitlements: {
            adFree: cached.adFree,
            verifiedBadgeEligible: cached.verifiedBadgeEligible,
            prioritySupport: cached.prioritySupport,
          },
          verificationDisplayState: cached.verificationDisplayState,
          badgeDisplayState: cached.badgeDisplayState,
          customerPortalAvailable: false,
        });
        setFromCache(true);
      }
      setError(result.error.message);
    }
    setRefreshing(false);
  }, [userId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (!userId) return;
    const client = getSupabaseClient();
    if (!client) return;
    const channel = client
      .channel(`picom-verified-entitlements:${userId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "account_entitlements", filter: `subject_id=eq.${userId}` },
        () => {
          void refresh();
        },
      )
      .subscribe();
    const poll = window.setInterval(() => {
      void refresh();
    }, 120_000);
    return () => {
      window.clearInterval(poll);
      void client.removeChannel(channel);
    };
  }, [userId, refresh]);

  const openSafe = async (url: string) => {
    if (!isAllowedVerifiedExternalUrl(url)) {
      setError(t("verified.unsafeUrl"));
      return;
    }
    if (url.startsWith(accountCenterUrls.origin)) {
      onOpenAccountCenter(url);
      return;
    }
    const opened = await externalLinkService.openExternalUrl(url);
    if (!opened.ok) setError(externalLinkService.getUserFriendlyError(opened.reason));
  };

  const openPortal = async () => {
    const result = await picomVerifiedService.createPortal("/account/billing");
    if (!result.ok) {
      setError(result.error.message);
      return;
    }
    await openSafe(result.data.portalUrl);
  };

  return (
    <section className="account-settings-section" id="settings-account-verified" aria-label={t("verified.title")}>
      <h3 className="account-settings-section-title">{t("verified.title")}</h3>
      <div className="settings-status-card settings-feature-card">
        <small>{t("verified.help")}</small>
        {summary ? (
          <dl className="account-summary-meta">
            <div><dt>{t("verified.subscription")}</dt><dd>{summary.subscriptionStatus}</dd></div>
            <div><dt>{t("verified.adFree")}</dt><dd>{summary.entitlements.adFree ? t("verified.active") : t("verified.inactive")}</dd></div>
            <div><dt>{t("verified.verification")}</dt><dd>{summary.verificationDisplayState}</dd></div>
            <div><dt>{t("verified.badge")}</dt><dd>{summary.badgeDisplayState}</dd></div>
          </dl>
        ) : (
          <small>{refreshing ? t("verified.refreshing") : t("verified.unavailable")}</small>
        )}
        {fromCache ? <small>{t("verified.cached")}</small> : null}
        {error ? <small role="status">{error}</small> : null}
        <div className="settings-actions-row settings-actions-row--wrap">
          <button type="button" className="settings-inline-action" onClick={() => onOpenAccountCenter(accountCenterUrls.verified)}>
            {t("verified.manageWeb")}
          </button>
          <button type="button" className="settings-inline-action settings-inline-action--ghost" onClick={() => onOpenAccountCenter(accountCenterUrls.accountVerification)}>
            {t("verified.completeVerification")}
          </button>
          <button type="button" className="settings-inline-action settings-inline-action--ghost" disabled={!summary?.customerPortalAvailable} onClick={() => void openPortal()}>
            {t("verified.billingPortal")}
          </button>
          <button type="button" className="settings-inline-action settings-inline-action--ghost" disabled={refreshing} onClick={() => void refresh()}>
            {refreshing ? t("verified.refreshing") : t("verified.refresh")}
          </button>
        </div>
      </div>
    </section>
  );
}

/**
 * Allowlisted HTTPS hosts for PICOM Verified checkout / portal / Account Center opens.
 * Desktop must validate before shell.openExternal.
 */

const ACCOUNT_HOSTS = new Set([
  "account.picom.gg",
  "app.picom.gg",
  "picom.gg",
  "www.picom.gg",
  "auth.picom.gg",
  "support.picom.gg",
]);

function isStripeBillingHost(host: string): boolean {
  return (
    host === "checkout.stripe.com"
    || host === "billing.stripe.com"
    || host === "verify.stripe.com"
    || host.endsWith(".stripe.com")
  );
}

export function isAllowedVerifiedExternalUrl(url: string): boolean {
  try {
    const parsed = new URL(url.trim());
    if (parsed.protocol !== "https:") return false;
    if (parsed.username || parsed.password) return false;
    const host = parsed.hostname.toLowerCase();
    if (ACCOUNT_HOSTS.has(host)) return true;
    return isStripeBillingHost(host);
  } catch {
    return false;
  }
}
